-- Owner 06.11: tolerance fruit/veg ±20 %, other weighed ±10 %, no gram caps; whole rabbit ≈1.5 kg and piglet ≈3 kg ±20 %. Generated by src/tolerance.mjs toleranceSql().
UPDATE products SET profile=json_set(profile,'$.tolerance_bps',2000,'$.tolerance_cap_g',1000000) WHERE json_extract(profile,'$.mode')='WEIGHED' AND category IN ('fruit','vegetables') AND (json_extract(profile,'$.tolerance_bps')<>2000 OR json_extract(profile,'$.tolerance_cap_g')<>1000000);
UPDATE products SET profile=json_set(profile,'$.tolerance_bps',1000,'$.tolerance_cap_g',1000000) WHERE json_extract(profile,'$.mode')='WEIGHED' AND NOT category IN ('fruit','vegetables') AND (json_extract(profile,'$.tolerance_bps')<>1000 OR json_extract(profile,'$.tolerance_cap_g')<>1000000);
UPDATE products SET profile=json_set(profile,'$.ranges',json('[{"id":"whole","min_g":1200,"max_g":1800,"estimate_g":1500}]')) WHERE id='akhalkalaki--artur_rabbit_whole' AND json_extract(profile,'$.mode')='WHOLE_BY_WEIGHT';
UPDATE products SET profile=json_set(profile,'$.ranges',json('[{"id":"whole","min_g":2400,"max_g":3600,"estimate_g":3000}]')) WHERE id='akhalkalaki--artur_piglet_whole' AND json_extract(profile,'$.mode')='WHOLE_BY_WEIGHT';
